Try/Catch with unknown:
try { // attempts code that might throw
  riskyOperation(); // calls function with arguments
} catch (err: unknown) {
  if (err instanceof Error) { // conditionally executes following block
    console.log(err.message); // outputs message to developer console
  } else if (typeof err === 'string') {
    console.log(err); // outputs message to developer console
  } else if (err && typeof err === 'object' && 'message' in err) {
    console.log((err as { message: string }).message); // outputs message to developer console
  } else {
    console.log('Unexpected error type'); // outputs message to developer console
  }
}

