Nested Loops:
// 2D matrix with types
const matrix: number[][] = [ // declares variable with explicit type
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9]
];

// Nested for loops — element is typed as number
for (let row = 0; row < matrix.length; row++) { // iterates with counter variable
  for (let col = 0; col < matrix[row].length; col++) { // iterates with counter variable
    console.log(matrix[row][col].toFixed(2)); // typed number
  }
}

// for...of with destructuring — cleaner
for (const [rowIdx, row] of matrix.entries()) { // iterates with counter variable
  for (const [colIdx, value] of row.entries()) { // iterates with counter variable
    console.log(`[${rowIdx}][${colIdx}] = ${value}`); // outputs message to developer console
  }
}

// Typed labeled break
type SearchResult = { found: boolean; pos: [number, number] }; // creates reusable type alias
function findValue(matrix: number[][], target: number): SearchResult { // defines reusable function block
  outer: for (let i = 0; i < matrix.length; i++) {
    for (let j = 0; j < matrix[i].length; j++) { // iterates with counter variable
      if (matrix[i][j] === target) { // conditionally executes following block
        return { found: true, pos: [i, j] }; // returns value to calling code
      }
    }
  }
  return { found: false, pos: [-1, -1] }; // returns value to calling code
}

// Prefer flatMap over nested loops for transformations
const pairs = [1, 2, 3].flatMap(x => [2, 3, 4].map(y => [x, y])); // declares variable; type inferred
// [[1,2],[1,3],[1,4],[2,2],...]

