const client = new ChromaClient();
const collection = await client.createCollection({ name: 'docs' });

const documents = [
  'TypeScript adds static types to JavaScript',
  'Vector databases enable semantic search',
  'Node.js runs JavaScript on the server',
];
const embeddings = await embed(documents);

await collection.add({
  ids: documents.map((_, i) => `doc${i}`),
  embeddings,
  documents,
});

// Semantic search
async function search(query: string, n: number = 2) {
  const [queryEmb] = await embed([query]);
  const results = await collection.query({
    queryEmbeddings: [queryEmb],
    nResults: n,
  });
  return results.documents[0];
}

// Cosine similarity manual implementation
function cosineSimilarity(a: number[], b: number[]): number {
  const dot = a.reduce((sum, ai, i) => sum + ai * b[i], 0);
  const magA = Math.sqrt(a.reduce((sum, ai) => sum + ai * ai, 0));
  const magB = Math.sqrt(b.reduce((sum, bi) => sum + bi * bi, 0));
  return dot / (magA * magB);
}

