// Server-Sent Events with Express
import express from 'express';
import OpenAI from 'openai';

const app = express();
const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

app.get('/chat', async (req, res) => {
  const { prompt } = req.query;

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const stream = await client.chat.completions.create({
    model: 'gpt-4o-mini',
    messages: [{ role: 'user', content: prompt as string }],
    stream: true,
  });

  for await (const chunk of stream) {
    const content = chunk.choices[0]?.delta?.content || '';
    if (content) {
      res.write(`data: ${JSON.stringify({ content })}\n\n`);
    }
  }

  res.write('data: [DONE]\n\n');
  res.end();

  req.on('close', () => {
    stream.controller?.abort(); // cleanup on disconnect
  });
});

// WebSocket with ws library
import { WebSocketServer } from 'ws';

const wss = new WebSocketServer({ port: 8080 });

wss.on('connection', (ws) => {
  const controller = new AbortController();

  ws.on('message', async (data) => {
    const { prompt } = JSON.parse(data.toString());

    const stream = await client.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [{ role: 'user', content: prompt }],
      stream: true,
    });

    for await (const chunk of stream) {
      if (controller.signal.aborted) break;
      const content = chunk.choices[0]?.delta?.content || '';
      if (content) {
        ws.send(JSON.stringify({ type: 'chunk', content }));
      }
    }

    ws.send(JSON.stringify({ type: 'done' }));
  });

  ws.on('close', () => controller.abort());
});

