AI-Powered Search:
import OpenAI from 'openai';
import { z } from 'zod';

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

// Types
interface SearchResult {
  id: string;
  content: string;
  score: number;
  source: 'semantic' | 'keyword' | 'hybrid';
}

// Embedding cache
const embeddingCache = new Map<string, number[]>();

async function getEmbedding(text: string): Promise<number[]> {
  if (embeddingCache.has(text)) return embeddingCache.get(text)!;
  const response = await openai.embeddings.create({
    model: 'text-embedding-3-small',
    input: text,
  });
  const emb = response.data[0].embedding;
  embeddingCache.set(text, emb);
  return emb;
}

// Cosine similarity
function cosineSim(a: number[], b: number[]): number {
  const dot = a.reduce((s, ai, i) => s + ai * b[i], 0);
  const ma = Math.sqrt(a.reduce((s, ai) => s + ai * ai, 0));
  const mb = Math.sqrt(b.reduce((s, bi) => s + bi * bi, 0));
  return ma && mb ? dot / (ma * mb) : 0;
}

// BM25-like keyword scoring (simplified)
function keywordScore(query: string, doc: string): number {
  const terms = query.toLowerCase().split(/\\s+/);
  const docLower = doc.toLowerCase();
  return terms.filter((t) => docLower.includes(t)).length / terms.length;
}

// Hybrid search
async function hybridSearch(
  query: string,
  documents: string[],
  alpha: number = 0.5
): Promise<SearchResult[]> {
  const queryEmb = await getEmbedding(query);
  const docEmbeddings = await Promise.all(documents.map(getEmbedding));

  const results: SearchResult[] = documents.map((content, i) => {
    const semantic = cosineSim(queryEmb, docEmbeddings[i]);
    const keyword = keywordScore(query, content);
    const score = alpha * semantic + (1 - alpha) * keyword;
    return { id: `doc${i}`, content, score, source: score === semantic ? 'semantic' : 'hybrid' };
  });

  return results.sort((a, b) => b.score - a.score).slice(0, 5);
}

// Rerank with cross-encoder via LLM
type RerankedResult = { id: string; content: string; relevanceScore: number };

async function rerank(query: string, results: SearchResult[]): Promise<RerankedResult[]> {
  const response = await openai.chat.completions.create({
    model: 'gpt-4o-mini',
    messages: [
      {
        role: 'system',
        content: 'Rerank these results by relevance to the query. Output as JSON array with scores.',
      },
      {
        role: 'user',
        content: JSON.stringify({ query, results }),
      },
    ],
    response_format: { type: 'json_object' },
  });

  return JSON.parse(response.choices[0].message.content || '[]');
}

Building AI Agents in TypeScript:
import OpenAI from 'openai';
import { z } from 'zod';

const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

// Tool definitions (typed)
interface Tool {
  name: string;
  description: string;
  parameters: z.ZodTypeAny;
  execute: (args: unknown) => Promise<string>;
}

const tools: Tool[] = [
  {
    name: 'calculator',
    description: 'Evaluate a math expression',
    parameters: z.object({ expression: z.string() }),
    execute: async ({ expression }) => String(eval(expression)),
  },
  {
    name: 'current_time',
    description: 'Get the current date and time',
    parameters: z.object({}),
    execute: async () => new Date().toISOString(),
  },
];

// Agent state
interface AgentMessage {
  role: 'system' | 'user' | 'assistant' | 'tool';
  content: string;
  tool_call_id?: string;
  name?: string;
}

class Agent {
  private messages: AgentMessage[] = [];

  constructor(systemPrompt: string) {
    this.messages.push({ role: 'system', content: systemPrompt });
  }

  async run(userInput: string, maxSteps: number = 5): Promise<string> {
    this.messages.push({ role: 'user', content: userInput });

    for (let step = 0; step < maxSteps; step++) {
      const response = await client.chat.completions.create({
        model: 'gpt-4o-mini',
        messages: this.messages,
        tools: this.toolsToOpenAI(),
        tool_choice: 'auto',
      });

      const msg = response.choices[0].message;
      this.messages.push({ role: 'assistant', content: msg.content || '' });

      if (!msg.tool_calls || msg.tool_calls.length === 0) {
        return msg.content || 'No response';
      }

      for (const tc of msg.tool_calls) {
        const tool = tools.find((t) => t.name === tc.function.name);
        if (!tool) continue;

        const args = JSON.parse(tc.function.arguments);
        const result = await tool.execute(args);

        this.messages.push({
          role: 'tool',
          content: result,
          tool_call_id: tc.id,
          name: tc.function.name,
        });
      }
    }

    return 'Max steps reached';
  }

  private toolsToOpenAI(): OpenAI.Chat.Completions.ChatCompletionTool[] {
    return tools.map((t) => ({
      type: 'function' as const,
      function: {
        name: t.name,
        description: t.description,
        parameters: t.parameters as unknown as Record<string, unknown>,
      },
    }));
  }
}

// Usage
const agent = new Agent('You are a helpful assistant with tools.');
const answer = await agent.run('What time is it? And calculate 2 + 2 * 3');
console.log(answer);
